// GENERATED by parts/kip/sync_classic_rig.py from viewer/Kip-Demo.html. DO NOT EDIT BY HAND.
// The classic Kip rig (head_shell, visor, torso, limbs, Pro pegs) exactly as Kip-Demo.html builds it, so other pages show the same Kip.
// Refresh:  python3 parts/kip/sync_classic_rig.py        Staleness check:  python3 parts/kip/sync_classic_rig.py --check
export function createClassicKip({ THREE, STLLoader, mergeVertices, toCreasedNormals, KIP_BUILD_VERSION }) {
  const stlLoader = new STLLoader();

async function loadSTL(url, creaseDeg = 38) {
  const bustedUrl = (url.startsWith('blob:') || url.includes('?')) ? url : `${url}?v=${KIP_BUILD_VERSION}`;
  const raw = await stlLoader.loadAsync(bustedUrl);
  raw.deleteAttribute('normal');
  const merged = mergeVertices(raw, 1e-4);
  merged.computeVertexNormals();
  return creaseDeg > 0 ? toCreasedNormals(merged, THREE.MathUtils.degToRad(creaseDeg)) : merged;
}

function scadMesh(geo, mat) {
  const m = new THREE.Mesh(geo, mat);
  m.rotation.x = -Math.PI / 2;
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

const mats = {
  shell: new THREE.MeshPhysicalMaterial({ color: '#f4efe6', roughness: 0.54, clearcoat: 0.12, clearcoatRoughness: 0.48, envMapIntensity: 0.62 }),
  hood:  new THREE.MeshPhysicalMaterial({ color: '#ccc1ae', roughness: 0.58, clearcoat: 0.08, clearcoatRoughness: 0.52, envMapIntensity: 0.58 }),
  spark: new THREE.MeshPhysicalMaterial({ color: '#ff6b4a', roughness: 0.34, metalness: 0.02, clearcoat: 0.42, clearcoatRoughness: 0.24, envMapIntensity: 0.78 }),
  visor: new THREE.MeshPhysicalMaterial({ color: '#1c2338', roughness: 0.28, metalness: 0.03, clearcoat: 0.42, clearcoatRoughness: 0.28, envMapIntensity: 0.52 }),
  eyes:  new THREE.MeshPhysicalMaterial({ color: '#b8e8ff', roughness: 0.24, clearcoat: 0.6, emissive: '#b8e8ff', emissiveIntensity: 0.32 }),
  glints: new THREE.MeshBasicMaterial({ color: '#ffffff' }),
  cheeks: new THREE.MeshPhysicalMaterial({ color: '#ff6b4a', roughness: 0.36, clearcoat: 0.35 }),
  snapSky:  new THREE.MeshPhysicalMaterial({ color: '#4eb3fc', roughness: 0.34, clearcoat: 0.50, envMapIntensity: 0.75 }),
  snapMint: new THREE.MeshPhysicalMaterial({ color: '#43d69c', roughness: 0.34, clearcoat: 0.50, envMapIntensity: 0.75 }),
  snapGold: new THREE.MeshPhysicalMaterial({ color: '#f8c232', roughness: 0.34, clearcoat: 0.50, envMapIntensity: 0.75 }),
  proSlate: new THREE.MeshPhysicalMaterial({ color: '#36405c', roughness: 0.38, metalness: 0.18, clearcoat: 0.38, envMapIntensity: 0.80 }),
  proGear:  new THREE.MeshPhysicalMaterial({ color: '#f0b238', roughness: 0.32, metalness: 0.14, clearcoat: 0.45, envMapIntensity: 0.82 }),
};

function buildKipRig(geos, partspec) {
  const mover = new THREE.Group();
  mover.name = 'kip_Mover';

  const grounder = new THREE.Group();
  grounder.name = 'kip_Grounder';
  mover.add(grounder);

  // Every physical piece is wrapped in a pure leaf Group (`partSlot`) — never an ancestor of another partSlot!
  const partSlots = [];
  function createSlot(id, parent, explodeVec, waveOrder, edition = 'both', guideTo = null) {
    const grp = new THREE.Group();
    grp.name = `slot_${id}`;
    parent.add(grp);
    const entry = {
      id, grp, parent,
      explodeVec: new THREE.Vector3(...explodeVec),
      waveOrder, // 0..5 assembly wave index
      edition,   // 'both' | 'pro' | 'snap'
      guideTo,   // optional target slot id for dashed assembly line
      localCentroid: new THREE.Vector3(),
      pilePos: new THREE.Vector3(),
      pileCentroid: new THREE.Vector3(),
      pileQuat: new THREE.Quaternion(),
      assembledWorldPos: new THREE.Vector3(),
      assembledWorldQuat: new THREE.Quaternion(),
      horizRadius: 12,
      t0: 0.4,
      dur: 0.62,
      arcExtra: 0,
    };
    partSlots.push(entry);
    return grp;
  }

  function addProPegMesh(slot, isBig, axis = 'y') {
    const g = isBig ? geos.spark_peg_big : geos.spark_peg_sml;
    const h = (isBig ? 9.0 : 8.0) * 0.92;
    const m = scadMesh(g, mats.spark);
    m.position.y = -h / 2;
    if (axis === 'x') {
      const wrap = new THREE.Group();
      wrap.add(m);
      wrap.rotation.z = Math.PI / 2;
      slot.add(wrap);
    } else {
      slot.add(m);
    }
  }

  function addSnapTurretMesh(slot, isBig, axis = 'y') {
    const g = isBig ? geos.snap_turret_big : geos.snap_turret;
    const h = (isBig ? 9.0 : 8.0) * 1.15;
    const m = scadMesh(g, mats.spark);
    m.position.y = -h / 2;
    if (axis === 'x') {
      const wrap = new THREE.Group();
      wrap.add(m);
      wrap.rotation.z = Math.PI / 2;
      slot.add(wrap);
    } else {
      slot.add(m);
    }
  }

  // Real PartSpec Pro hardware helpers (convert print-oriented [-Y, Z=0..5] STL into centered Z-axis or X-axis part)
  function makePinFrictionZ(mat = mats.spark) {
    const g = new THREE.Group();
    const m = new THREE.Mesh(partspec.pinFriction, mat);
    m.castShadow = true;
    m.position.set(0, 12.5, -2.5);
    g.add(m);
    g.rotation.x = -Math.PI / 2; // axis along Z (-12.5 .. +12.5)
    return g;
  }

  function makeShaftTu03Z(mat = mats.proSlate) {
    const g = new THREE.Group();
    const m = new THREE.Mesh(partspec.shaftTu03, mat);
    m.castShadow = true;
    m.position.set(0, 18.75, -2.5);
    g.add(m);
    g.rotation.x = -Math.PI / 2; // axis along Z (-18.75 .. +18.75), double-D flats along +-Y!
    return g;
  }

  // --- HIPS / TORSO CORE (pivot at y = 61.5 mm) ---
  const hips = new THREE.Group();
  hips.name = 'kip_Hips';
  hips.position.set(0, 61.5, 0);
  grounder.add(hips);

  const torsoOffset = new THREE.Group();
  torsoOffset.position.y = -61.5;
  hips.add(torsoOffset);

  const proTorsoSlot = createSlot('torso_pro', torsoOffset, [0, 0, 0], 2, 'pro');
  proTorsoSlot.add(scadMesh(geos.torso, mats.shell));

  const snapTorsoSlot = createSlot('torso_snap', torsoOffset, [0, 0, 0], 2, 'snap');
  snapTorsoSlot.add(scadMesh(geos.snap_torso, mats.shell));
  snapTorsoSlot.visible = false;

  const backStudsSlot = createSlot('back_studs', torsoOffset, [0, 8, -42], 2.3, 'both', 'torso_anchor');
  backStudsSlot.add(scadMesh(geos.back_dock_studs, mats.spark));

  // Neck Connectors (Pro Peg vs Snap Turret)
  const neckAnchor = new THREE.Group();
  neckAnchor.position.set(0, 106.8 - 61.5, 0);
  hips.add(neckAnchor);

  const proNeckPeg = createSlot('neck_peg', neckAnchor, [0, 20, 0], 3.8, 'pro');
  addProPegMesh(proNeckPeg, true, 'y');

  const snapNeckTurret = createSlot('neck_turret', neckAnchor, [0, 20, 0], 3.8, 'snap');
  addSnapTurretMesh(snapNeckTurret, true, 'y');
  snapNeckTurret.visible = false;

  // --- SHARED HEAD ASSEMBLY (100% identical across Pro 8+ and Snap 3+!) ---
  const head = new THREE.Group();
  head.name = 'kip_Head';
  head.position.set(0, 45.3, 0);
  hips.add(head);

  const headLocal = new THREE.Group();
  headLocal.position.y = 1.2;
  head.add(headLocal);

  const headShellSlot = createSlot('head_shell', headLocal, [0, 42, 0], 4.0, 'both', 'neck_anchor');
  headShellSlot.add(scadMesh(geos.head_shell, mats.shell));

  const headHoodSlot = createSlot('head_hood', headLocal, [0, 46, -34], 4.25, 'both', 'head_shell');
  headHoodSlot.add(scadMesh(geos.head_hood, mats.hood));

  const crownSlot = createSlot('crown', headLocal, [0, 64, 0], 4.55, 'both', 'head_shell');
  const crownBudsMesh = scadMesh(geos.crown_buds, mats.spark);
  const crownBlankMesh = scadMesh(geos.crown_cap_blank, mats.hood);
  crownBlankMesh.visible = false;
  crownSlot.add(crownBudsMesh, crownBlankMesh);

  const earPodLSlot = createSlot('ear_pod_l', headLocal, [30, 42, 0], 4.4, 'both', 'head_shell');
  earPodLSlot.add(scadMesh(geos.ear_pod_l, mats.spark));

  const earPodRSlot = createSlot('ear_pod_r', headLocal, [-30, 42, 0], 4.4, 'both', 'head_shell');
  earPodRSlot.add(scadMesh(geos.ear_pod_r, mats.spark));

  const visorSlot = createSlot('visor', headLocal, [0, 42, 32], 4.35, 'both', 'head_shell');
  const visorMesh = scadMesh(geos.visor, mats.visor);
  visorSlot.add(visorMesh);

  const faceDetailSlot = createSlot('face_details', headLocal, [0, 42, 50], 4.5, 'both', 'visor');
  const faceDetailGrp = new THREE.Group();
  faceDetailGrp.add(
    scadMesh(geos.face_eyes, mats.eyes),
    scadMesh(geos.face_glints, mats.glints),
    scadMesh(geos.face_cheeks, mats.cheeks)
  );
  faceDetailSlot.add(faceDetailGrp);

  // --- ARMS (Pro 2-segment + pegs vs Snap 1-piece curved sleeve + turrets; 100% SHARED 3-finger hands!) ---
  // Spherical Rodrigues Pivot Flex for Snap (`3+`) 1-piece limbs:
  // Keeps physical `snap_arm.stl` / `snap_leg.stl` 100% 1-piece for 3D printing & Exploded/Pile views,
  // while smoothly flexing mid-limb elbows & knees during character animations!
  function makeFlexSnapLimb(srcGeo, mat, offsetY, midY, midZ, band) {
    const g = srcGeo.clone();
    g.rotateX(-Math.PI / 2);
    g.translate(0, offsetY, 0);
    const posAttr = g.attributes.position;
    const normAttr = g.attributes.normal;
    const restPos = new Float32Array(posAttr.array);
    const restNorm = new Float32Array(normAttr.array);
    const count = posAttr.count;
    const weights = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      const ry = restPos[i * 3 + 1];
      weights[i] = THREE.MathUtils.smoothstep(midY - ry, -band, band);
    }
    const mesh = new THREE.Mesh(g, mat);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    let isDirty = false;

    function deform(qDistal) {
      let qx = qDistal.x, qy = qDistal.y, qz = qDistal.z, qw = qDistal.w;
      if (qw < 0) { qx = -qx; qy = -qy; qz = -qz; qw = -qw; }
      const sinHalf = Math.hypot(qx, qy, qz);
      if (sinHalf < 1e-4) {
        if (isDirty) {
          posAttr.array.set(restPos);
          normAttr.array.set(restNorm);
          posAttr.needsUpdate = true;
          normAttr.needsUpdate = true;
          isDirty = false;
        }
        return;
      }
      const ux = qx / sinHalf, uy = qy / sinHalf, uz = qz / sinHalf;
      const theta = 2.0 * Math.acos(Math.min(1.0, qw));
      const pArr = posAttr.array;
      const nArr = normAttr.array;
      for (let i = 0; i < count; i++) {
        const w = weights[i];
        const i3 = i * 3;
        if (w <= 1e-4) {
          pArr[i3]     = restPos[i3];
          pArr[i3 + 1] = restPos[i3 + 1];
          pArr[i3 + 2] = restPos[i3 + 2];
          nArr[i3]     = restNorm[i3];
          nArr[i3 + 1] = restNorm[i3 + 1];
          nArr[i3 + 2] = restNorm[i3 + 2];
          continue;
        }
        const ang = w * theta;
        const c = Math.cos(ang), s = Math.sin(ang), omc = 1.0 - c;
        const vx = restPos[i3], vy = restPos[i3 + 1] - midY, vz = restPos[i3 + 2] - midZ;
        const vDot = ux * vx + uy * vy + uz * vz;
        pArr[i3]     = vx * c + (uy * vz - uz * vy) * s + ux * vDot * omc;
        pArr[i3 + 1] = midY + vy * c + (uz * vx - ux * vz) * s + uy * vDot * omc;
        pArr[i3 + 2] = midZ + vz * c + (ux * vy - uy * vx) * s + uz * vDot * omc;

        const nx = restNorm[i3], ny = restNorm[i3 + 1], nz = restNorm[i3 + 2];
        const nDot = ux * nx + uy * ny + uz * nz;
        nArr[i3]     = nx * c + (uy * nz - uz * ny) * s + ux * nDot * omc;
        nArr[i3 + 1] = ny * c + (uz * nx - ux * nz) * s + uy * nDot * omc;
        nArr[i3 + 2] = nz * c + (ux * ny - uy * nx) * s + uz * nDot * omc;
      }
      posAttr.needsUpdate = true;
      normAttr.needsUpdate = true;
      isDirty = true;
    }

    return { mesh, deform };
  }

  const joints = { Hips: hips, Head: head };
  const editionParts = { pro: [proTorsoSlot, proNeckPeg], snap: [snapTorsoSlot, snapNeckTurret] };
  const flexArms = {};
  const flexLegs = {};
  const snapWriAnchors = {};
  const snapAnkAnchors = {};

  for (const side of [1, -1]) {
    const tag = side === 1 ? 'Left' : 'Right';
    const sTag = side === 1 ? 'l' : 'r';

    const shoAnchor = new THREE.Group();
    shoAnchor.position.set(side * 17.2, 33.5, 0);
    hips.add(shoAnchor);

    const proShoPeg = createSlot(`sho_peg_${sTag}`, shoAnchor, [side * 18, 4, 0], 2.8, 'pro');
    addProPegMesh(proShoPeg, true, 'x');
    editionParts.pro.push(proShoPeg);

    const snapShoTurret = createSlot(`sho_turret_${sTag}`, shoAnchor, [side * 18, 4, 0], 2.8, 'snap');
    addSnapTurretMesh(snapShoTurret, true, 'x');
    snapShoTurret.visible = false;
    editionParts.snap.push(snapShoTurret);

    const arm = new THREE.Group();
    arm.name = `kip_${tag}Arm`;
    arm.position.set(side * 18.2, 33.5, 0);
    hips.add(arm);

    // Pro Upper Arm + Elbow Peg
    const uaSlot = createSlot(`upper_arm_${sTag}`, arm, [side * 36, 0, 0], 3.0, 'pro', `sho_peg_${sTag}`);
    const ua = scadMesh(geos.upper_arm, mats.shell);
    ua.position.y = -23.0;
    uaSlot.add(ua);
    editionParts.pro.push(uaSlot);

    const elbAnchor = new THREE.Group();
    elbAnchor.position.set(0, -23.8, 0);
    arm.add(elbAnchor);
    const elbPegSlot = createSlot(`elb_peg_${sTag}`, elbAnchor, [side * 46, -10, 0], 3.15, 'pro', `upper_arm_${sTag}`);
    addProPegMesh(elbPegSlot, false, 'y');
    editionParts.pro.push(elbPegSlot);

    // Snap 1-Piece Curved Arm + Wrist Turret (digital "fake elbow" flex around (0, -17.5, 1.2) during animations!)
    const snapArmSlot = createSlot(`snap_arm_${sTag}`, arm, [side * 38, -6, 0], 3.05, 'snap', `sho_turret_${sTag}`);
    const flexArm = makeFlexSnapLimb(geos.snap_arm, mats.shell, -34.6, -17.5, 1.2, 8.0);
    snapArmSlot.add(flexArm.mesh);
    snapArmSlot.visible = false;
    editionParts.snap.push(snapArmSlot);
    flexArms[tag] = flexArm;

    const snapWriAnchor = new THREE.Group();
    snapWriAnchor.position.set(0, -35.0, 3.8);
    snapWriAnchor.rotation.x = THREE.MathUtils.degToRad(-11);
    arm.add(snapWriAnchor);
    snapWriAnchors[tag] = snapWriAnchor;
    const snapWriTurret = createSlot(`snap_wri_${sTag}`, snapWriAnchor, [side * 52, -20, 4], 3.25, 'snap', `snap_arm_${sTag}`);
    addSnapTurretMesh(snapWriTurret, false, 'y');
    snapWriTurret.visible = false;
    editionParts.snap.push(snapWriTurret);

    // ForeArm node (in Snap mode, repositions cleanly onto snap_arm's cuff so the SHARED Hand mates 1:1!)
    const foreArm = new THREE.Group();
    foreArm.name = `kip_${tag}ForeArm`;
    foreArm.position.set(0, -23.8, 0);
    arm.add(foreArm);

    const faSlot = createSlot(`forearm_${sTag}`, foreArm, [side * 56, -20, 0], 3.3, 'pro', `elb_peg_${sTag}`);
    const fa = scadMesh(geos.forearm, mats.shell);
    fa.position.y = -21.8;
    faSlot.add(fa);
    editionParts.pro.push(faSlot);

    const wriAnchor = new THREE.Group();
    wriAnchor.position.set(0, -22.6, 0);
    foreArm.add(wriAnchor);
    const wriPegSlot = createSlot(`wri_peg_${sTag}`, wriAnchor, [side * 64, -32, 0], 3.45, 'pro', `forearm_${sTag}`);
    addProPegMesh(wriPegSlot, false, 'y');
    editionParts.pro.push(wriPegSlot);

    // 100% SHARED Sleek 3-Finger + Thumb Hand!
    const hand = new THREE.Group();
    hand.name = `kip_${tag}Hand`;
    hand.position.set(0, -22.6, 0);
    foreArm.add(hand);

    const handRestOrient = new THREE.Group();
    handRestOrient.rotation.y = -side * Math.PI / 2;
    hand.add(handRestOrient);

    const hWrap = new THREE.Group();
    hWrap.rotation.z = Math.PI;
    hWrap.position.y = -0.8;
    handRestOrient.add(hWrap);

    const handSlot = createSlot(`hand_${sTag}`, hWrap, [side * 74, -44, 8], 3.6, 'both');
    handSlot.add(scadMesh(side === 1 ? geos.hand_l : geos.hand_r, mats.shell));

    joints[`${tag}Arm`] = arm;
    joints[`${tag}ForeArm`] = foreArm;
    joints[`${tag}Hand`] = hand;
    if (side === -1) joints.rightHandCgripParent = handRestOrient;
  }

  // --- LEGS & 100% SHARED 1x2 TU SNEAKER BOOTS ---
  const snapStandingLegSlots = [];
  const bootSlots = [];
  for (const side of [1, -1]) {
    const tag = side === 1 ? 'Left' : 'Right';
    const sTag = side === 1 ? 'l' : 'r';

    const hipAnchor = new THREE.Group();
    hipAnchor.position.set(side * 10.8, 0, 0);
    hips.add(hipAnchor);

    const proHipPeg = createSlot(`hip_peg_${sTag}`, hipAnchor, [side * 8, -14, 0], 1.5, 'pro');
    addProPegMesh(proHipPeg, true, 'y');
    editionParts.pro.push(proHipPeg);

    const snapHipTurret = createSlot(`hip_turret_${sTag}`, hipAnchor, [side * 8, -14, 0], 1.5, 'snap');
    addSnapTurretMesh(snapHipTurret, true, 'y');
    snapHipTurret.visible = false;
    editionParts.snap.push(snapHipTurret);

    const upLeg = new THREE.Group();
    upLeg.name = `kip_${tag}UpLeg`;
    upLeg.position.set(side * 10.8, 0, 0);
    hips.add(upLeg);

    // Pro Thigh + Knee Peg
    const thSlot = createSlot(`thigh_${sTag}`, upLeg, [side * 14, -28, 0], 1.25, 'pro', `hip_peg_${sTag}`);
    const th = scadMesh(geos.thigh, mats.shell);
    th.position.y = -24.8;
    thSlot.add(th);
    editionParts.pro.push(thSlot);

    const kneAnchor = new THREE.Group();
    kneAnchor.position.set(0, -25.6, 0);
    upLeg.add(kneAnchor);
    const knePegSlot = createSlot(`kne_peg_${sTag}`, kneAnchor, [side * 18, -42, 0], 1.0, 'pro', `thigh_${sTag}`);
    addProPegMesh(knePegSlot, false, 'y');
    editionParts.pro.push(knePegSlot);

    // Snap 1-Piece Chunky Trouser-Leg + Ankle Turret (digital "fake knee" flex around (0, -19.6, 0) during animations!)
    const snapLegSlot = createSlot(`snap_leg_${sTag}`, upLeg, [side * 16, -34, 0], 1.1, 'snap', `hip_turret_${sTag}`);
    const flexLeg = makeFlexSnapLimb(geos.snap_leg, mats.shell, -38.6, -19.6, 0.0, 8.5);
    snapLegSlot.add(flexLeg.mesh);
    snapLegSlot.visible = false;
    editionParts.snap.push(snapLegSlot);
    flexLegs[tag] = flexLeg;

    const snapAnkAnchor = new THREE.Group();
    snapAnkAnchor.position.set(0, -39.2, 0);
    upLeg.add(snapAnkAnchor);
    snapAnkAnchors[tag] = snapAnkAnchor;
    const snapAnkTurret = createSlot(`snap_ank_${sTag}`, snapAnkAnchor, [side * 20, -54, 0], 0.7, 'snap', `snap_leg_${sTag}`);
    addSnapTurretMesh(snapAnkTurret, false, 'y');
    snapAnkTurret.visible = false;
    editionParts.snap.push(snapAnkTurret);

    // Leg node (in Snap mode, repositions cleanly onto snap_leg's cuff so the SHARED Boot mates 1:1!)
    const leg = new THREE.Group();
    leg.name = `kip_${tag}Leg`;
    leg.position.set(0, -25.6, 0);
    upLeg.add(leg);

    const shSlot = createSlot(`shin_${sTag}`, leg, [side * 22, -56, 0], 0.75, 'pro', `kne_peg_${sTag}`);
    const sh = scadMesh(geos.shin, mats.shell);
    sh.position.y = -25.2;
    shSlot.add(sh);
    editionParts.pro.push(shSlot);

    const ankAnchor = new THREE.Group();
    ankAnchor.position.set(0, -26.0, -1.2);
    leg.add(ankAnchor);
    const ankPegSlot = createSlot(`ank_peg_${sTag}`, ankAnchor, [side * 25, -70, 0], 0.45, 'pro', `shin_${sTag}`);
    addProPegMesh(ankPegSlot, false, 'y');
    editionParts.pro.push(ankPegSlot);

    // 100% SHARED 1x2 TU Sneaker Boot!
    const foot = new THREE.Group();
    foot.name = `kip_${tag}Foot`;
    foot.position.set(0, -26.0, -1.5);
    leg.add(foot);

    const bootSlot = createSlot(`boot_${sTag}`, foot, [side * 28, -84, 8], 0.0, 'both');
    const bt = scadMesh(geos.boot, mats.shell);
    bt.position.set(0, -13.6, 1.5);
    bootSlot.add(bt);
    snapStandingLegSlots.push(snapHipTurret, snapLegSlot, snapAnkTurret);
    bootSlots.push(bootSlot);

    joints[`${tag}UpLeg`] = upLeg;
    joints[`${tag}Leg`] = leg;
    joints[`${tag}Foot`] = foot;
  }

  // =========================================================================
  // 5 MODULAR TU ACCESSORY ZONES (100% Compatible with BOTH Pro 8+ & Snap 3+!)
  // =========================================================================

  // ZONE 1: 1x2 CROWN DOCK
  const crownAccSlot = createSlot('crown_acc', headLocal, [0, 84, 0], 5.0, 'both', 'crown');
  const pointyEars = scadMesh(partspec.pointyEars, mats.snapGold);
  pointyEars.position.set(0, 42.2, 0);
  pointyEars.visible = false;
  const wobbleHat = scadMesh(partspec.wobbleHat, mats.snapMint);
  wobbleHat.position.set(6.25, 42.2, 0);
  wobbleHat.visible = false;
  crownAccSlot.add(pointyEars, wobbleHat);

  // ZONE 2: ±X EAR-POD Ø6.6 BOSSES
  const snapEarPods = new THREE.Group();
  snapEarPods.visible = false;
  headLocal.add(snapEarPods);
  for (const side of [1, -1]) {
    const sTag = side === 1 ? 'l' : 'r';
    const earAccSlot = createSlot(`ear_acc_${sTag}`, snapEarPods, [side * 58, 44, 0], 5.1, 'both', `ear_pod_${sTag}`);
    const earGeo = side === 1 ? geos.ear_acc_l : geos.ear_acc_r;
    const earMesh = new THREE.Mesh(earGeo, mats.snapMint);
    earMesh.castShadow = true;
    earMesh.receiveShadow = true;
    const basis = new THREE.Matrix4().makeBasis(
      new THREE.Vector3(0, -side, 0),
      new THREE.Vector3(0, 0, -1),
      new THREE.Vector3(side, 0, 0)
    );
    earMesh.quaternion.setFromRotationMatrix(basis);
    earMesh.position.set(side * 23.8, 20.0, 0);
    earAccSlot.add(earMesh);
  }

  const proEarScanner = new THREE.Group();
  proEarScanner.visible = false;
  headLocal.add(proEarScanner);
  const proEarSlot = createSlot('pro_ear_scanner', proEarScanner, [-62, 46, 8], 5.1, 'both', 'ear_pod_r');
  const proEarPivot = new THREE.Group();
  proEarPivot.position.set(-23.8, 20.0, 0);
  proEarPivot.rotation.x = THREE.MathUtils.degToRad(-28);
  const earBeamWrap = new THREE.Group();
  earBeamWrap.rotation.y = -Math.PI / 2;
  const earBeamMesh = new THREE.Mesh(partspec.beamTu03, mats.proSlate);
  earBeamMesh.castShadow = true;
  earBeamMesh.position.set(12.5, 0, 0);
  earBeamWrap.add(earBeamMesh);
  // Real PartSpec shaft_tu03 + gear_spur_z10 + bushing_half collars keyed on double-D flats!
  const earRadarGear = new THREE.Group();
  earRadarGear.position.set(25.0, 0, 0);
  const earShaft = makeShaftTu03Z(mats.proSlate);
  earShaft.position.z = 9.375;
  earRadarGear.add(earShaft);
  const earBushBack = new THREE.Mesh(partspec.bushingHalf, mats.proGear);
  earBushBack.castShadow = true;
  earBushBack.position.z = -6.25;
  earRadarGear.add(earBushBack);
  const earGearMesh = new THREE.Mesh(partspec.gearZ10, mats.spark);
  earGearMesh.castShadow = true;
  earGearMesh.position.z = 12.5;
  earRadarGear.add(earGearMesh);
  const earBushFront = new THREE.Mesh(partspec.bushingHalf, mats.proGear);
  earBushFront.castShadow = true;
  earBushFront.position.z = 18.75;
  earRadarGear.add(earBushFront);
  earBeamWrap.add(earRadarGear);
  proEarPivot.add(earBeamWrap);
  proEarSlot.add(proEarPivot);

  // ZONE 3: 2x2 BACK DOCK (4-hole Cloud Wings on 2x2 studs, OR flush Pro 2:1 Gears on central Ø7.0 bore!)
  const wingsGroup = new THREE.Group();
  wingsGroup.visible = false;
  hips.add(wingsGroup);
  const wingsSlot = createSlot('cloud_wings', wingsGroup, [0, 22, -92], 5.2, 'both', 'back_studs');
  const wingsHolder = new THREE.Group();
  wingsHolder.position.set(0, 87.5 - 61.5, -13.6);
  const cloudWings = new THREE.Mesh(partspec.cloudWings, mats.snapSky);
  cloudWings.castShadow = true;
  cloudWings.receiveShadow = true;
  cloudWings.rotation.y = Math.PI; // z=0 2x2 sockets snap centered onto all 4 Back Dock studs!
  wingsHolder.add(cloudWings);
  wingsSlot.add(wingsHolder);

  const proBackGroup = new THREE.Group();
  proBackGroup.visible = false;
  hips.add(proBackGroup);
  const proBackSlot = createSlot('pro_back_gears', proBackGroup, [0, 22, -96], 5.2, 'both', 'torso_anchor');
  const proBackRig = new THREE.Group();
  proBackRig.position.set(0, 87.5 - 61.5, -13.4);
  proBackRig.rotation.z = THREE.MathUtils.degToRad(-28);
  const beam = new THREE.Mesh(partspec.beamTu05, mats.proSlate);
  beam.castShadow = true;
  beam.position.set(0, 0, -12.5);
  proBackRig.add(beam);
  // Real PartSpec pin_friction (2 TU = 25 mm) locking beam_str_tu05 center bore into Kip's central Ø7.0 back bore!
  proBackRig.add(makePinFrictionZ(mats.spark));

  function buildBackGearAxle(gx, gearGeo, gearMat, phaseRad = 0) {
    const axleGrp = new THREE.Group();
    axleGrp.position.set(gx, 0, 0);
    axleGrp.rotation.z = phaseRad;
    const sh = makeShaftTu03Z(mats.proSlate);
    sh.position.z = -18.75; // z = -37.5 .. 0.0 (flush with beam front face!)
    axleGrp.add(sh);
    const bInner = new THREE.Mesh(partspec.bushingHalf, mats.proSlate);
    bInner.castShadow = true;
    bInner.position.z = -18.75;
    axleGrp.add(bInner);
    const gMesh = new THREE.Mesh(gearGeo, gearMat);
    gMesh.castShadow = true;
    gMesh.position.z = -25.0;
    axleGrp.add(gMesh);
    const bOuter = new THREE.Mesh(partspec.bushingHalf, mats.proGear);
    bOuter.castShadow = true;
    bOuter.position.z = -31.25;
    axleGrp.add(bOuter);
    return axleGrp;
  }
  const gearBig = buildBackGearAxle(-12.5, partspec.gearZ20, mats.proGear, 0);
  const gearSml = buildBackGearAxle( 25.0, partspec.gearZ10, mats.spark, Math.PI / 10);
  proBackRig.add(gearBig, gearSml);
  proBackSlot.add(proBackRig);

  // ZONE 4: 1x1 LOWER-BACK TAIL PORT (Exact 2.0 TU = 25.0 mm below Back Dock: z_scad = 62.5 -> y_hips = 1.0!)
  const snapTailGroup = new THREE.Group();
  snapTailGroup.visible = false;
  hips.add(snapTailGroup);
  const snapTailSlot = createSlot('tail_wag', snapTailGroup, [0, -18, -76], 5.3, 'both', 'torso_anchor');
  const snapTailPivot = new THREE.Group();
  snapTailPivot.position.set(0, 1.0, -13.1);
  snapTailPivot.rotation.x = -0.22;
  const tailMesh = new THREE.Mesh(geos.tail_acc, mats.spark);
  tailMesh.castShadow = true;
  tailMesh.receiveShadow = true;
  snapTailPivot.add(tailMesh);
  snapTailSlot.add(snapTailPivot);

  const proTailGroup = new THREE.Group();
  proTailGroup.visible = false;
  hips.add(proTailGroup);
  const proTailSlot = createSlot('tail_pro_wheelie', proTailGroup, [0, -22, -82], 5.3, 'both', 'torso_anchor');
  const proTailRig = new THREE.Group();
  proTailRig.position.set(0, 1.0, -13.1);
  const tailStrut = new THREE.Group();
  tailStrut.rotation.x = THREE.MathUtils.degToRad(26);
  // 1) Real shaft_tu03 + bushing_half pinning cross_connector_tu01 axle_z into Kip's z = 62.5 pelvis bore!
  const tailMountShaft = makeShaftTu03Z(mats.proSlate);
  tailMountShaft.position.set(0, 0, -6.25);
  tailStrut.add(tailMountShaft);
  const tailMountBush = new THREE.Mesh(partspec.bushingHalf, mats.spark);
  tailMountBush.castShadow = true;
  tailMountBush.position.set(0, 0, -18.75);
  tailStrut.add(tailMountBush);
  const tailCross = new THREE.Mesh(partspec.crossConnector, mats.spark);
  tailCross.castShadow = true;
  tailCross.rotation.z = -Math.PI / 2;
  tailCross.position.set(0, -6.25, -12.5); // axle_z at (0, 0, -12.5..0), perpendicular axle_y along X at (0, -12.5, -6.25)!
  tailStrut.add(tailCross);
  // 2) Real beam_str_tu03 alongside cross_connector_tu01 (x = -18.75 .. -6.25) pinned by shaft_tu03 + bushings!
  const tailBeam = new THREE.Mesh(partspec.beamTu03, mats.proSlate);
  tailBeam.castShadow = true;
  tailBeam.rotation.y = Math.PI / 2;
  tailBeam.position.set(-18.75, -12.5, -18.75);
  tailStrut.add(tailBeam);
  const crossAxleWrap = new THREE.Group();
  crossAxleWrap.position.set(-6.25, -12.5, -6.25);
  crossAxleWrap.rotation.y = Math.PI / 2; // Z -> +X (-18.75 .. +18.75 -> world x = -25.0 .. +12.5)
  crossAxleWrap.add(makeShaftTu03Z(mats.proSlate));
  for (const bz of [-18.75, 12.5]) {
    const b = new THREE.Mesh(partspec.bushingHalf, mats.proGear);
    b.castShadow = true;
    b.position.z = bz;
    crossAxleWrap.add(b);
  }
  tailStrut.add(crossAxleWrap);
  // 3) Dead-center (x = 0) wheel_tu04 on real shaft_tu03 + bushing_half collars at bore 2 (2 TU = 25 mm back)!
  const tailWheelWrap = new THREE.Group();
  tailWheelWrap.position.set(0, -12.5, -31.25);
  tailWheelWrap.rotation.y = Math.PI / 2;
  const tailWheel = new THREE.Group(); // spins wheel + keyed shaft + outer collars together!
  const tailWheelAxle = makeShaftTu03Z(mats.proSlate);
  tailWheelAxle.position.z = -6.25;
  tailWheel.add(tailWheelAxle);
  const tailWheelMesh = new THREE.Mesh(partspec.wheelTu04, mats.proGear);
  tailWheelMesh.castShadow = true;
  tailWheelMesh.position.z = -6.25; // world x = -6.25 .. +6.25 (exact midline x = 0!)
  tailWheel.add(tailWheelMesh);
  for (const bz of [-25.0, 6.25]) {
    const b = new THREE.Mesh(partspec.bushingHalf, mats.spark);
    b.castShadow = true;
    b.position.z = bz;
    tailWheel.add(b);
  }
  tailWheelWrap.add(tailWheel);
  tailStrut.add(tailWheelWrap);
  proTailRig.add(tailStrut);
  proTailSlot.add(proTailRig);

  // ZONE 5: RIGHT HAND Ø 6.6 mm SHAFT + Z10 SPINNER + BUSHING COLLAR
  const proStaffGroup = new THREE.Group();
  proStaffGroup.visible = false;
  joints.rightHandCgripParent.add(proStaffGroup);
  const proStaffSlot = createSlot('pro_staff', proStaffGroup, [-102, -48, 22], 5.4, 'both', 'hand_r');
  const proStaff = new THREE.Group();
  proStaff.position.set(0, -11.4, 2.3);
  const tipWrap = new THREE.Group();
  tipWrap.rotation.y = Math.PI / 2; // local Z -> +X
  const tipGear = new THREE.Group(); // spins shaft_tu05 + gear_spur_z10 + bushing_half together!
  const shaftHolder = new THREE.Group();
  const shaftMesh = new THREE.Mesh(partspec.shaftTu05, mats.proSlate);
  shaftMesh.castShadow = true;
  shaftMesh.position.set(0, 31.25, -2.5);
  shaftHolder.add(shaftMesh);
  shaftHolder.rotation.x = -Math.PI / 2; // double-D flats along +-Y matching gearZ10 & bushingHalf!
  shaftHolder.position.z = -4.0;
  tipGear.add(shaftHolder);
  const tipGearMesh = new THREE.Mesh(partspec.gearZ10, mats.snapSky);
  tipGearMesh.castShadow = true;
  tipGearMesh.position.z = -31.25;
  tipGear.add(tipGearMesh);
  const tipBush = new THREE.Mesh(partspec.bushingHalf, mats.spark);
  tipBush.castShadow = true;
  tipBush.position.z = -25.0;
  tipGear.add(tipBush);
  tipWrap.add(tipGear);
  proStaff.add(tipWrap);
  proStaffSlot.add(proStaff);

  return {
    mover, grounder, hips, joints, partSlots, editionParts, createSlot,
    flexArms, flexLegs, snapWriAnchors, snapAnkAnchors,
    neckAnchor, proNeckPeg, snapNeckTurret,
    headLocal, headShellSlot, headHoodSlot, crownSlot, earPodLSlot, earPodRSlot, visorSlot, faceDetailSlot,
    crownAccSlot, snapStandingLegSlots, bootSlots,
    backStudsSlot,
    crownBudsMesh, crownBlankMesh, visorMesh, faceDetailGrp,
    pointyEars, wobbleHat,
    snapEarPods, proEarScanner, earRadarGear,
    wingsGroup, proBackGroup,
    snapTailGroup, snapTailPivot, proTailGroup, tailWheel,
    proStaffGroup, gearBig, gearSml, tipGear
  };
}

  const STL_NAMES = [
  'head_shell', 'head_hood', 'crown_buds', 'crown_cap_blank',
  'ear_pod_l', 'ear_pod_r', 'visor', 'face_eyes', 'face_glints', 'face_cheeks',
  'torso', 'back_dock_studs', 'upper_arm', 'forearm', 'hand_l', 'hand_r',
  'thigh', 'shin', 'boot', 'spark_peg_big', 'spark_peg_sml',
  'ear_acc_l', 'ear_acc_r', 'tail_acc',
  'snap_torso', 'snap_arm', 'snap_leg', 'snap_turret_big', 'snap_turret'
];

  // PartSpec Pro hardware the rig receives as `partspec` (same files and crease angles as the demo's init()).
  const PARTSPEC = [
    ['pointyEars', '/kip/partspec/toyventor_pointy_ears_S.stl', 35],
    ['wobbleHat', '/kip/partspec/toyventor_wobble_hat_S.stl', 35],
    ['cloudWings', '/kip/partspec/toyventor_cloud_wings_S.stl', 35],
    ['beamTu03', '/kip/partspec/toyventor_beam_str_tu03_P.stl', 35],
    ['beamTu05', '/kip/partspec/toyventor_beam_str_tu05_P.stl', 35],
    ['gearZ20', '/kip/partspec/toyventor_gear_spur_z20_P.stl', 25],
    ['gearZ10', '/kip/partspec/toyventor_gear_spur_z10_P.stl', 25],
    ['shaftTu05', '/kip/partspec/toyventor_shaft_tu05_P.stl', 35],
    ['shaftTu03', '/kip/partspec/toyventor_shaft_tu03_P.stl', 35],
    ['pinFriction', '/kip/partspec/toyventor_pin_friction_P.stl', 35],
    ['bushingHalf', '/kip/partspec/toyventor_bushing_half_P.stl', 30],
    ['crossConnector', '/kip/partspec/toyventor_cross_connector_tu01_P.stl', 35],
    ['wheelTu04', '/kip/partspec/toyventor_wheel_tu04_P.stl', 30]
  ];

  async function loadGeos() {
    const [geosArr, partArr] = await Promise.all([
      Promise.all(STL_NAMES.map(async (n) => [n, await loadSTL(`/kip/stls/${n}.stl`, 38)])),
      Promise.all(PARTSPEC.map(([, url, crease]) => loadSTL(url, crease))),
    ]);
    return { geos: Object.fromEntries(geosArr), baseParts: Object.fromEntries(PARTSPEC.map(([key], i) => [key, partArr[i]])) };
  }

  return { loadSTL, scadMesh, mats, buildKipRig, loadGeos, STL_NAMES };
}
